Inductive tte_res : Type :=
| TTE_nm                 (* [comment removed for export] *)
| TTE_ctl                (* [comment removed for export] *)
| TTE_cr_nm              (* [comment removed for export] *)
| TTE_badle              (* [comment removed for export] *)
| TTE_ok (i : nat).      (* [comment removed for export] *)

Definition tte_class (bs : list byte) : tte_res :=
  match find_ix is_ctl bs with
  | None => TTE_nm
  | Some i =>
      match nth_error bs i with
      | Some c => if zb c =? 13 then
                    match nth_error bs (S i) with
                    | None => TTE_cr_nm
                    | Some d => if zb d =? 10 then TTE_ok i else TTE_badle
                    end
                  else TTE_ctl
      | None => TTE_ctl (* [comment removed for export] *)
      end
  end.

Definition tte_ret (r : tte_res) (P L : Z) : Z :=
  match r with TTE_ctl => 0 | TTE_ok i => P + Z.of_nat i + 2 | _ => L end.

Definition tte_ec (r : tte_res) (E0 : ecv) : ecv :=
  match r with
  | TTE_nm => EC_http_loc HE_NEED_MORE LOC_TTE_NM
  | TTE_cr_nm => EC_http_loc HE_NEED_MORE LOC_TTE_NM2
  | TTE_badle => EC_http_loc HE_BAD_LINE_ENDING LOC_TTE_BADLE
  | _ => E0
  end.

Definition tte_tl (r : tte_res) (P : Z) (tj : list byte) : list cell :=
  match r with TTE_ok i => [C8 (wz (P + Z.of_nat i))] | _ => [CB 8 tj] end.

(* [comment removed for export] *)
Definition tte_cat (r : tte_res) (g : bool) : bool :=
  match r with TTE_ctl | TTE_ok _ => g | _ => true end.

