Definition tte_W (lo : Z) (sp : word) (T E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (T, T + 8); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

(* [comment removed for export] *)
Definition tte_post_r (r : tte_res) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P T E lo : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (tte_ret r P (P + Z.of_nat (length bs)))) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (tte_W lo sp T E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ bytes_at usegs m' P bs
    /\ rw_cells usegs m' T (tte_tl r P tj)
    /\ rw_cells usegs m' E (ErrCodeCells (tte_ec r E0))
    /\ HttpCat m' (tte_cat r g) /\ XStatics m'.

Definition tte_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P T E lo : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj : list byte) (m : mem) : machine_state -> Prop :=
  tte_post_r (tte_class bs) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P T E lo bs E0 g tj m.

Definition tte_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P T E lo : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj : list byte),
  bytes_at usegs m P bs ->
  rw_cells usegs m T [CB 8 tj] ->
  rw_cells usegs m E (ErrCodeCells E0) -> ec_ok E0 ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp -> 0xb8000 <= lo ->
  ((0 < P /\ P + Z.of_nat (length bs) <= 0x10000) \/ 0x95090 <= P) -> P + Z.of_nat (length bs) <= lo ->
  bv_unsigned sp <= T -> T + 8 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (T + 8 <= E \/ E + 24 <= T) ->
  mem_inv usegs m ->
  evt usegs (tte_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P T E lo bs E0 g tj m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz (P + Z.of_nat (length bs))) (wz T) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_TOKEN_TO_EOL) fc None m (seg_rom usegs)).

