  intros CTX PURE;
  destruct CTX as (FRlo & FRhi & TL & EC & HC & XS & ST & WIN & MU & WM & MI);
  destruct PURE as (EOK & LO & IMG & PLO & PHI & TLO & THI & ELO & EHI & TE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold ErrCodeCells in EC;
  unfold tte_W, G_HTTP_CAT in *;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold wz;
  (* [comment removed for export] *)
  step; step; step; step;
  call_assignA_with (bv_unsigned sp + -48) (bv_unsigned sp + -48) e lo g junk;
  clear HC XS;
  lazymatch goal with
  | TMP : rw_cells _ _ (bv_unsigned sp + -48) (ErrCodeCells _), HC : HttpCat _ true, XS : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP;
    (* [comment removed for export] *)
    steps_to 0x3fc5c%Z;
    expose_statics HC XS [(lo, bv_unsigned sp); (E, E + 24)]%Z;
    unfold ErrCodeCells, wz in EC;
    (* [comment removed for export] *)
    step; step; st1; st1; st1;
    (* [comment removed for export] *)
    step; step; step; step;
    join_frame TMP FRhi (bv_unsigned sp + -48);
    step; release_frame TMP ST' (bv_unsigned sp); step;
    lazymatch goal with
    | MU2 : munch [(lo, bv_unsigned sp); (E, E + 24)]%Z ?mx _, WM2 : wmono _ ?mx _ |- _ => finish_tte XS MU2 WM2
    end
  end.
